def taylor(self, x, n):
    v0 = 0
    for v1 in range(n):
        v0 += (-1) ** v1 * (x / (180 * pi)) ** (2 * v1) / factorial(2 * v1)
    return v0

def cos(self, x):
    if x == 0:
        return 1
    return sum(((-1) ** v0 * x ** (2 * v0) / factorial(2 * v0) for v0 in range(100)))

def factorial(self, a):
    if a == 0:
        return 1
    return a * self.factorial(a - 1)

def factorial(self, a):
    if a == 0:
        return 1
    return a * self.factorial
